import{_ as d,C as s,o as n,c as e,j as t,E as l,a as r,a2 as o}from"./chunks/framework.C21TwvGF.js";const x=JSON.parse(`{"title":"1-hafta (Mentor)","description":"","frontmatter":{"title":"1-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (BI)","link":"/mentor/9-sinf-bi/"},"n":1,"bob":"I-bob · Ma’lumotlar tahliliga kirish va Excel bilan ishlash","lessons":[{"g":1,"title":"Ma’lumot tushunchasi, uning turlari va DIKW modeli","lead":"Raqamlar olamiga kirish: xom ma'lumotlar qanday qilib foydali axborot, chuqur bilim va oqilona qarorlarga aylanishini DIKW piramidasi orqali kashf eting.","link":"/mentor/9-sinf-bi/hafta-01/dars-1","slide":"/slaydlar/9-sinf-bi/hafta-01/dars-1.html","test":"/slaydlar/9-sinf-bi/hafta-01/dars-1-test.html"},{"g":2,"title":"Business Intelligence (BI) asoslari: Katta to'rtlik va hayotiy sikl","lead":"Ma'lumotlarni strategik kuchga aylantiring: zamonaviy Business Intelligence arxitekturasi, tahlilning Katta to'rtligi va qaror qabul qilish sikli bilan tanishing.","link":"/mentor/9-sinf-bi/hafta-01/dars-2","slide":"/slaydlar/9-sinf-bi/hafta-01/dars-2.html","test":"/slaydlar/9-sinf-bi/hafta-01/dars-2-test.html"},{"g":3,"title":"BI tizimlari turlari, mutaxassislik rollari va Excel analitik platformasi","lead":"Katta biznes qanday boshqariladi: BI tizimlarining turlari, jamoaviy rollar va barcha tahlillar poydevori bo'lgan Microsoft Excel bilan yaqindan tanishing.","link":"/mentor/9-sinf-bi/hafta-01/dars-3","slide":"/slaydlar/9-sinf-bi/hafta-01/dars-3.html","test":"/slaydlar/9-sinf-bi/hafta-01/dars-3-test.html"}],"test":"/slaydlar/9-sinf-bi/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-bi/hafta-01/index.md","filePath":"mentor/9-sinf-bi/hafta-01/index.md"}`),h={name:"mentor/9-sinf-bi/hafta-01/index.md"},m={class:"blk"},u={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},g={class:"blk"},b={id:"baholash-mezoni",tabindex:"-1"};function k(c,a,f,v,q,y){const i=s("Icon");return n(),e("div",null,[t("div",m,[t("h2",u,[l(i,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_1-dars-ma-lumot-tushunchasi-va-dikw-modeli" tabindex="-1">1-dars: Ma’lumot tushunchasi va DIKW modeli <a class="header-anchor" href="#_1-dars-ma-lumot-tushunchasi-va-dikw-modeli" aria-label="Permalink to &quot;1-dars: Ma’lumot tushunchasi va DIKW modeli&quot;">​</a></h2><ol><li>O&#39;zingiz qiziqqan biror soha (masalan, futbol klubi, maktab kutubxonasi yoki mobil ilova) faoliyatini tanlang.</li><li>Tanlagan sohangiz bo&#39;yicha DIKW piramidasining har bir pog&#39;onasiga mos 1 tadan aniq hayotiy misol keltiring: <ul><li><strong>Data (Ma&#39;lumot):</strong> Kamida 3 ta xom son va matnli fakt.</li><li><strong>Information (Axborot):</strong> Faktlarga vaqt, joy va shaxs kontekstini qo&#39;shib gap tuzing.</li><li><strong>Knowledge (Bilim):</strong> Hodisaning sabab-oqibat qonuniyatini ifodalang (&quot;Nega bunday bo&#39;ldi?&quot;).</li><li><strong>Wisdom (Donolik):</strong> Bilimga tayanib qabul qilinadigan aniq boshqaruv qarorini yozing.</li></ul></li></ol><hr><h2 id="_2-dars-business-intelligence-bi-asoslari-katta-to-rtlik" tabindex="-1">2-dars: Business Intelligence (BI) asoslari: Katta to&#39;rtlik <a class="header-anchor" href="#_2-dars-business-intelligence-bi-asoslari-katta-to-rtlik" aria-label="Permalink to &quot;2-dars: Business Intelligence (BI) asoslari: Katta to&#39;rtlik&quot;">​</a></h2><ol><li>Biror xizmat ko&#39;rsatish shoxobchasi (masalan, kafe, avtomobil yuvish shoxobchasi yoki yetkazib berish xizmati) misolida tahlilning &quot;Katta to&#39;rtligi&quot; bo&#39;yicha 4 ta tahliliy jumla tuzing: <ul><li><strong>Tavsifiy (Deskriptiv):</strong> O&#39;tgan haftadagi aniq savdo/xizmat natijasi.</li><li><strong>Diagnostik:</strong> Natijaga nima sabab bo&#39;lgani haqidagi tahlil.</li><li><strong>Bashoratli (Prediktiv):</strong> Kelgusi haftadagi ehtimoliy talab prognozi.</li><li><strong>Retseptiv (Preskriptiv):</strong> Ko&#39;proq daromad olish uchun biznes egasiga tavsiya.</li></ul></li><li>ETL jarayonining 3 ta bosqichini o&#39;z so&#39;zlaringiz bilan qisqacha izohlang.</li></ol><hr><h2 id="_3-dars-bi-tizimlari-turlari-va-excel-analitik-platformasi" tabindex="-1">3-dars: BI tizimlari turlari va Excel analitik platformasi <a class="header-anchor" href="#_3-dars-bi-tizimlari-turlari-va-excel-analitik-platformasi" aria-label="Permalink to &quot;3-dars: BI tizimlari turlari va Excel analitik platformasi&quot;">​</a></h2><ol><li>Microsoft Excel yoki Google Sheets dasturini oching.</li><li>O&#39;zingizning oilaviy haftalik xarajatlaringiz bo&#39;yicha 5 ta qatordan iborat tartibli jadval tuzing: <ul><li>Ustunlar: <code>Xarajat nomi</code> (Text), <code>Sana</code> (Date), <code>Miqdori</code> (Number), <code>Narxi</code> (Currency), <code>Izoh</code> (Text).</li><li>Kataklarga qiymatlarni to&#39;g&#39;ri formatda kiriting (son yoniga qo&#39;lda so&#39;z yozmang).</li></ul></li><li>Jadval skrinshotini oling yoki faylni mentorga topshiring.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>1-dars vazifasi (30 ball):</strong> DIKW pog&#39;onalari to&#39;g&#39;ri ajratilgani (har bir pog&#39;ona 7.5 balldan). Data va Information o&#39;rtasidagi farq aniq bo&#39;lishi lozim.</li><li><strong>2-dars vazifasi (35 ball):</strong> Katta to&#39;rtlik tahlil turlari mantiqan to&#39;g&#39;ri qo&#39;llangani va ETL tushunchasi to&#39;liq yoritilgani.</li><li><strong>3-dars vazifasi (35 ball):</strong> Excelda jadval tuzilmasi, ma&#39;lumot turlarining to&#39;g&#39;ri tanlangani va hisob-kitob buzilmagani.</li></ul><h3 id="tezkor-tekshirish-bo-yicha-eslatma" tabindex="-1">Tezkor tekshirish bo&#39;yicha eslatma <a class="header-anchor" href="#tezkor-tekshirish-bo-yicha-eslatma" aria-label="Permalink to &quot;Tezkor tekshirish bo&#39;yicha eslatma&quot;">​</a></h3><ul><li>Agar o&#39;quvchi Excelda narx yoniga qo&#39;lda &quot;so&#39;m&quot; deb yozgan bo&#39;lsa, formatlash qoidasini eslatib, xatolikni ko&#39;rsatib bering.</li></ul>',16))]),t("div",g,[t("h2",b,[l(i,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Mavzular:</strong></p><ol><li>Ma’lumot tushunchasi, uning turlari va DIKW modeli (Data, Information, Knowledge, Wisdom)</li><li>Business Intelligence (BI) asoslari: BI arxitekturasi, Katta to&#39;rtlik (Deskriptiv, Diagnostik, Prediktiv, Preskriptiv) va hayotiy sikl</li><li>BI tizimlari arxitekturasi, sohadagi mutaxassislik rollari va Excel analitik platformasi</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Ma&#39;lumot va DIKW</strong></td><td>Xom ma&#39;lumot va axborot farqi, miqdoriy/sifat turlari, DIKW pog&#39;onalari mantig&#39;i</td><td>30 ball</td></tr><tr><td><strong>BI va Katta To&#39;rtlik</strong></td><td>BI arxitekturasi, Katta to&#39;rtlik (Deskriptiv, Diagnostik, Prediktiv, Preskriptiv), ETL va DWH</td><td>35 ball</td></tr><tr><td><strong>BI Tizimlari va Excel</strong></td><td>BI turlari (operatsional/strategik/self-service/embedded), mutaxassis rollari, Excel muhiti va turlari</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>DIKW &amp; Turlar (30)</th><th>BI &amp; Katta To&#39;rtlik (35)</th><th>BI Turlari &amp; Excel (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar Data (xom ma&#39;lumot) va Information (axborot) o&#39;rtasidagi farqni aralashtirib yuborishlari mumkin. Kontekstning ahamiyatini (&quot;38&quot; raqami harorat ekanligi aytilgandagina axborot bo&#39;lishi) tushuntirish kerak. Shuningdek, Excelda katakka son yoniga so&#39;z yozish (<code>15000 so&#39;m</code>) oqibatida formula ishlamay qolishini amalda ko&#39;rsatish zarur.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> Power BI Desktop dasturini o&#39;rnatib ko&#39;rish yoki oddiy Excel datasetidan ilk interaktiv doiraviy grafik yaratish topshirig&#39;i berilishi mumkin.</li></ul>',11))])])}const I=d(h,[["render",k]]);export{x as __pageData,I as default};
